protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // 1. Discriminator renamed from "Discriminator" to "$type" in EF Core 9.
    //    Preserve old name so existing documents remain queryable.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // 2. id format changed from "Blog|1" to "1" in EF Core 9.
    //    Preserve old compound format so existing documents stay accessible.
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // 3. HasIndex now throws for Cosmos entities — removed.
    //    Cosmos indexing is managed via the container's indexing policy.
}

